package com.bank.metrics.service;

import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class NameMetricsService {
    private static final Logger log = Logger.getLogger(NameMetricsService.class.getName());

    public List<Integer> nameLengths(List<String> names) {
        log.info(() -> "Computing lengths for " + names.size() + " names");
        return names.stream()
                .mapToInt(String::length)   // IntStream — no boxing during compute
                .boxed()                    // box back to Integer only at the end
                .collect(Collectors.toList());
    }
}
